// Package connpool implements an adaptive connection pool with circuit breaking,
// exponential backoff, health checking, per-endpoint concurrency caps, and
// graceful degradation under load.
package connpool

import (
	"context"
	"errors"
	"math"
	"math/rand"
	"sort"
	"sync"
	"sync/atomic"
	"time"
)

// ── State types ──────────────────────────────────────────────────────────
type State int
const (
	StateClosed   State = iota
	StateOpen
	StateHalfOpen
)

var (
	ErrCircuitOpen    = errors.New("circuit breaker: open")
	ErrPoolExhausted  = errors.New("pool: exhausted")
	ErrEndpointCapped = errors.New("endpoint: concurrency cap reached")
	ErrTimedOut       = errors.New("pool: queue timeout")
)

// ── Config ───────────────────────────────────────────────────────────────
type Config struct {
	FailureThreshold        int
	HalfOpenMaxRequests     int
	RecoveryTimeout         time.Duration
	BaseBackoff             time.Duration
	MaxBackoff              time.Duration
	TargetLatencyP50        time.Duration
	TargetLatencyP95        time.Duration
	MaxQueueDepth           int
	MinConnections          int
	MaxConnections          int
	ResizeInterval          time.Duration
	HealthCheckInterval     time.Duration
	HealthCheckTimeout      time.Duration
	EndpointConcurrencyCaps map[string]int
}

type ConnFunc        func(ctx context.Context, endpoint string) error
type HealthCheckFunc func(ctx context.Context, endpoint string) error
type ReleaseFunc     func(latency time.Duration, err error)

// ── Pool ─────────────────────────────────────────────────────────────────
type Pool struct {
	config   Config
	dialFn   ConnFunc
	healthFn HealthCheckFunc
	endpoints sync.Map         // map[string]*endpointState
	globalActive atomic.Int64
	globalTotal  atomic.Int64
	ctx          context.Context
	cancel       context.CancelFunc
	wg           sync.WaitGroup
	latencySamples []time.Duration
	latencyMu      sync.Mutex
	maxSamples     int
	once           sync.Once
}
